data: {"index":1,"delta":{"text":"# Kyoto: A Journey Through the Heart of","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" Old Japan\n\nWhile Tokyo represents the neon-lit, high-speed future of Japan, Kyoto remains its soulful, beating","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" heart. As the imperial capital for over a thousand years, Kyoto is a city where time seems to move differently. Here","type":"text"},"event_type":"step.delta"}

