data: {"index":1,"delta":{"text":" **Tenryu-ji Temple** offers one of the finest Zen gardens in the country, designed to incorporate the surrounding","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" mountains into its landscape.\n\n### 3. Fushimi Inari-taisha: The Path of Ten Thousand","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" Gates\nPerhaps the most iconic image of Japan is the vermilion tunnel of torii gates at **Fushimi In","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":"ari-taisha**. Dedicated to the Shinto god of rice and prosperity, the shrine features thousands of gates that wind","type":"text"},"event_type":"step.delta"}

